INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'i18n_mapping', '{\"assetState\":{\"en\":{\"1\":\"In stock\",\"2\":\"Not in stock\",\"3\":\"Suspended\"},\"cn\":{\"1\":\"在库\",\"2\":\"出库\",\"3\":\"停用\"}},\"chartType\":{\"en\":{\"line\":\"Line Chart\",\"bar\":\"Histogram\",\"table\":\"Table\",\"stackArea\":\"Stack Area\",\"singleStat\":\"SingleStat\",\"url\":\"URL\",\"alertList\":\"Alert list\",\"text\":\"Text\"},\"cn\":{\"line\":\"曲线图\",\"bar\":\"柱状图\",\"table\":\"表格\",\"stackArea\":\"堆叠区域图\",\"singleStat\":\"SingleStat\",\"url\":\"URL\",\"alertList\":\"告警列表\",\"text\":\"文本\"}}}', 1, NULL);

delete from sys_config where param_key = "asset_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'asset_export_header', '{\"cn\":{\"*SN码\":\"资产序列号，唯一标识(必填) \\n示例: A0420200101\",\"*资产类型\":\"设备类型（必填） \\n示例: server\",\"*厂商\":\"厂商（必填） \\n示例: Cisco\",\"*型号\":\"型号(必填) \\n示例: CISCO-UCS-C220\",\"*数据中心\":\"数据中心(必填) \\n示例: 北京电信中心机房\",\"机柜\":\"机柜 \\n示例: cabinet-001\",\"开始U位\":\"机柜开始位置 此信息一般和机柜结束位置联合使用 \\n示例: 1\",\"结束U位\":\"机柜结束位置 此信息一般与机柜开始位置联合使用 \\n示例: 2\",\"*主机地址\":\"主机地址(必填),IP格式 \\n示例: 172.0.0.1\",\"状态\":\"资产状态，可选: 在库、出库、停用 \\n示例: 在库\",\"购买日期\":\"购买日期 \\n示例: 2020/2/25\",\"SSH账号端口\":\"SSH连接端口 \\n示例: 22\",\"SSH账号登录名\":\"SSH账号登录名 \\n示例: root\",\"SSH登录认证方式\":\"SSH登录认证方式 密码登录:password,密钥登录:key \\n示例: password\",\"SSH登录密码\":\"SSH登录密码 认证方式为password时登录密码 \\n示例: xxxxx\",\"SSH登录密钥\":\"SSH登录密钥 \\n示例: ssh-rsa CFdv7Jez6K...\",\"SSH密钥密码\":\"SSH密钥密码 \\n示例: xxxxx\",\"TELNET账号端口\":\"TELNET账号端口 \\n示例: 23\",\"TELNET账号登录名\":\"TELNET账号登录名 \\n示例: root\",\"TELNET用户名提示\":\"TELNET用户名提示 \\n示例: user\",\"TELNET登录密码\":\"TELNET登录密码 \\n示例: xxxxx\",\"TELNET密码提示\":\"TELNET密码提示 \\n示例: pass\",\"TELNET重启密码提示\":\"TELNET重启密码提示 \\n示例: pass\",\"SNMP账号端口\":\"SNMP账号端口 \\n示例: 161\",\"SNMP团体名\":\"SNMP团体名 \\n示例: public\",\"SNMP上下文名称\":\"SNMP上下文名称 \\n示例: 80002b8046h\",\"SNMP协议版本\":\"SNMP协议版本 支持V2和V3 \\n示例: 2\",\"SNMP用户名\":\"SNMPV3版本时,登录用户名 \\n示例: root\",\"SNMP安全级别\":\"SNMP安全级别 noAuthNoPriv(不认证不加密) authNoPriv(认证不加密) authPriv(认证且加密) \\n示例: noAuthNoPriv\",\"SNMP用户密码\":\"SNMP用户密码, 根据安全级别选择填写 \\n示例: xxxxx\",\"SNMP认证协议\":\"SNMP用户认证协议 MD5、SHA \\n示例: MD5\",\"SNMP加密协议\":\"SNMP加密协议 AES、DES \\n示例: AES\",\"SNMP加密密码\":\"SNMP加密密码 \\n示例: xxxxx\",\"资产标签\":\"资产标签,tag信息,格式: key=value 如需填写多个请使用回车换行 \\n示例: isOpen=true \\n isHighPerformance=true\",\"Exporter\":\"是否安装内置node_exporter，1：安装，0：不安装 \\n示例：1\"},\"en\":{\"*Sn\":\"Asset serial number, unique identifier (required) \\nExample: A0420200101\",\"*Type\":\"Asset type (required) \\nExample: server\",\"*Vendor\":\"Vendor (required) \\nExample: Cisco\",\"*Model\":\"Model (required) \\nExample: CISCO-UCS-C220\",\"*IDC\":\"Data Center (Required) \\nExample: Beijing Telecom Center Computer Room\",\"Cabinet\":\"Cabinet \\nExample: cabinet-001\",\"Cabinet Start\":\"Cabinet start position This information is generally used in conjunction with the cabinet end position \\nExample: 1\",\"Cabinet End\":\"Cabinet end position This information is generally used in conjunction with the cabinet start position \\nExample: 2\",\"*Host\":\"Host address (required), IP format \\nExample: 172.0.0.1\",\"State\":\"Asset status, optional: In stock, Not in stock or Suspended \\nExample: In stock\",\"PurchaseDate\":\"Purchase date \\nExample: 2020/2/25\",\"SSH Account Port\":\"SSH account connection port \\nExample: 22\",\"SSH UserName\":\"SSH account login name \\nExample: root\",\"Methed\":\"SSH login authentication method, Password login: password, key login: key \\nExample: password\",\"SSH Password\":\"SSH login password The login password when the authentication method is password \\nExample: xxxxx\",\"PrivateKey\":\"SSH login key file \\nExample: ssh-rsa CFdv7Jez6K...\",\"Key Password\":\"SSH key password \\nExample: xxxxx\",\"TELNET Port\":\"TELNET account port \\nExample: 23\",\"TELNET Username\":\"TELNET account login name \\nExample: root\",\"User Tip\":\"TELNET username prompt \\nExample: user\",\"TELNET Password\":\"TELNET login password \\nExample: xxxxx\",\"Password Tip\":\"TELNET password prompt \\nExample: pass\",\"Relogin Tip\":\"TELNET relogin password prompt \\nExample: pass\",\"SNMP port\":\"SNMP account port \\nExample: 161\",\"Community\":\"SNMP community name \\nExample: public\",\"Context Name\":\"SNMP context name \\nExample: 80002b8046h\",\"Version\":\"SNMP protocol version supports V2 and V3 \\nExample: 2\",\"SNMP User\":\"In SNMPV3 version, login user name\\nExample: root\",\"SecurityLevel\":\"SNMP security level noAuthNoPriv (no authentication and no encryption) authNoPriv (authentication and no encryption) authPriv (authentication and encryption) \\nExample: noAuthNoPriv\",\"SNMP Password\":\"SNMP user password, fill in according to the security level \\nExample: xxxxx\",\"Auth Protocol\":\"SNMP auth protocol MD5, SHA \\nExample: MD5\",\"Priv Protocol\":\"SNMP priv protocol AES, DES \\nExample: AES\",\"Priv Password\":\"SNMP priv password \\nExample: xxxxx\",\"Tags\":\"Asset tag information, format: key=value If you need to fill in more than one, please use carriage return and line feed \\nExample: isOpen=true \\n isHighPerformance=true\",\"Exporter\":\"Whether to install the built-in node_exporter, 1: install, 0: not install \\nExample: 1\"}}', 1, 'asset导出表头');


/*  module endpoint 表增加 labels 列 */
ALTER TABLE module ADD COLUMN labels VARCHAR (256) COMMENT '使用json对象保存{"key":"value"}';
ALTER TABLE endpoint ADD COLUMN labels VARCHAR (256) COMMENT '使用json对象保存{"key":"value"}';

/*  endpoint 导入导出表头增加 label 列  */
DELETE FROM sys_config WHERE param_key = "endpoint_export_header";
INSERT INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'endpoint_export_header', '{\"cn\":{\"*系统\":\"系统名称(必填) \\n示例: Nezha\",\"*组件\":\"组件名称(必填) \\n示例: node_exporter\",\"*组件类型\":\"组件类型(必填) 可选: HTTP、SNMP 当type = SNMP时，组件必须存在 \\n示例: HTTP\",\"资产序列号\":\"资产序列号(非必填) 与 主机地址 不能同时为空 \\n示例: A0420200101\",\"端口号\":\"端口号 范围0-65535 \\n示例: 9100\",\"参数\":\"端点查询参数，JSON格式， \\n示例: {\\\"key\\\":\\\"value\\\"}\",\"标签\":\"标签，JSON格式， \\n示例: {\\\"key\\\":\\\"value\\\"}\",\"*路径\":\"路径（必填） 请求路径，\\n示例: /metrics\",\"主机地址\":\"主机地址（非必填） 与 资产序列号 不能同时为空 \\n示例; 127.0.0.1\"},\"en\":{\"*Project Name\":\"Project Name(Required) \\nExample: Nezha\",\"*Module Name\":\"Module Name(Required) \\nExample: node_exporter\",\"*Module Type\":\"Module type(Required) Optional: HTTP or SNMP，When type = SNMP, the component must exist \\nExample: HTTP\",\"Sn\":\"Asset serial number(Not required) And host address cannot be empty at the same time \\nExample: A0420200101\",\"Port\":\"Port number range 0-65535 \\nExample: 9100\",\"Parameter\":\"Endpoint query parameters, JSON format  \\nExample: {\\\"key\\\":\\\"value\\\"}\",\"Labels\":\"Endpoint lebel, JSON format  \\nExample: {\\\"key\\\":\\\"value\\\"}\",\"*Path\":\"Path (required) Request path \\nExample: /metrics\",\"Host\":\"Host address (not required) and asset serial number cannot be empty at the same time \\nExample; 127.0.0.1\"}}', 1, NULL);
